  "suggestedArticles": {
    "title": "Essential Pakistan Vehicle & Tax Guides",
    "html": "<div class=\"grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n  <a href=\"/blogs/pakistan-vehicle-tax-guide/\" class=\"block rounded-xl border border-hairline bg-canvas p-4 hover:border-primary transition dark:border-overlay-lighter dark:bg-surface dark:hover:border-primary\">\n    <span class=\"text-xs font-bold uppercase tracking-wider text-primary\">Token Tax &amp; Excise</span>\n    <h3 class=\"font-semibold text-ink dark:text-on-primary mt-1\">Pakistan Vehicle Tax &amp; Token Rates Complete Guide</h3>\n    <p class=\"text-xs text-muted mt-1\">Comprehensive breakdown of Punjab, Sindh, KPK, and ICT token tax rates, ePay online payment, and MTMIS verification.</p>\n  </a>\n  <a href=\"/blogs/pakistan-pta-mobile-tax-guide/\" class=\"block rounded-xl border border-hairline bg-canvas p-4 hover:border-primary transition dark:border-overlay-lighter dark:bg-surface dark:hover:border-primary\">\n    <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Mobile &amp; Customs</span>\n    <h3 class=\"font-semibold text-ink dark:text-on-primary mt-1\">PTA Mobile Tax &amp; DIRBS Registration Guide</h3>\n    <p class=\"text-xs text-muted mt-1\">Calculate passport vs CNIC registration taxes for iPhone and Android devices.</p>\n  </a>\n  <a href=\"/blogs/pakistan-fbr-tax-slabs/\" class=\"block rounded-xl border border-hairline bg-canvas p-4 hover:border-primary transition dark:border-overlay-lighter dark:bg-surface dark:hover:border-primary\">\n    <span class=\"text-xs font-bold uppercase tracking-wider text-amber-600 dark:text-amber-400\">Active Taxpayer List</span>\n    <h3 class=\"font-semibold text-ink dark:text-on-primary mt-1\">FBR Tax Slabs &amp; ATL Compliance Guide</h3>\n    <p class=\"text-xs text-muted mt-1\">Avoid 100% to 200% non-filer penalty surcharges on vehicle registration and property purchases.</p>\n  </a>\n</div>"
  },
  "officialResources": {
    "title": "Official Provincial Excise & MTMIS Portals",
    "html": "<ul class=\"space-y-2 text-sm\">\n  <li><a href=\"https://excise.punjab.gov.pk/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Excise, Taxation &amp; Narcotics Control Department (Punjab)</a> — MTMIS Vehicle Verification &amp; ePay</li>\n  <li><a href=\"https://excise.gos.pk/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Excise &amp; Taxation Department (Sindh)</a> — Sindh Online Vehicle Verification &amp; Tax Portal</li>\n  <li><a href=\"https://islamabadexcise.gov.pk/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Excise &amp; Taxation Department (ICT Islamabad)</a> — Capital Territory Vehicle Registration Portal</li>\n  <li><a href=\"https://www.kpexcise.gov.pk/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Excise, Taxation &amp; Narcotics Control (KPK)</a> — Khyber Pakhtunkhwa MTMIS System</li>\n</ul>\n<p class=\"text-xs text-muted mt-3\">Always verify vehicle token status and tax clearance using the official provincial MTMIS databases before purchasing a motor vehicle.</p>"
  },
